def solve(payload):
    h, steps = payload["step_s"], payload["steps"]
    if h <= 0 or isinstance(steps, bool) or not isinstance(steps, int) or not 0 <= steps <= 1000:
        return {"error": "invalid_steps"}
    a, b = payload["rate_per_s"], payload["forcing_per_s"]
    y = payload["initial"]
    values = [y]
    for _ in range(steps):
        k1 = a*y+b
        k2 = a*(y+h*k1/2)+b
        k3 = a*(y+h*k2/2)+b
        k4 = a*(y+h*k3)+b
        y += h*(k1+2*k2+2*k3+k4)/6
        values.append(y)
    return {"values": values}

